    [9, 7, 9, 9, 7, 9, 9, 9, 8],   # row 3
    [0, 0, 0, 0, 0, 0, 0, 0, 0],   # row 4 - divider
]

divider_row = 4

non_bg_by_col = {}
for r in range(4):
    for c in range(9):
        v = grid[r][c]
        if v != 9:
            if c not in non_bg_by_col:
                non_bg_by_col[c] = []
            non_bg_by_col[c].append((r, v))

special_cols = [c for c, cells in non_bg_by_col.items() if len(cells) == 1]
print(f"Columns with single non-bg cells: {special_cols}")

# Build output properly with all 9 rows
output = [[0]*9 for _ in range(9)]

# Copy top half as-is
for r in range(divider_row):
    output[r] = grid[r][:]

# Divider row stays zeros
output[divider_row] = [0]*9

# Mirror bottom rows and fill special columns
# Row 5 <- row 3, Row 6 <- row 2, Row 7 <- row 1, Row 8 <- row 0
for r_bottom in range(divider_row + 1, 9):
    r_top_mirror = 3 - (r_bottom - divider_row - 1)  # 5->3, 6->2, 7->1, 8->0
    for c in special_cols:
        if r_top_mirror >= 0:
            src_val = grid[r_top_mirror][c]
            if src_val != 9:
                output[r_bottom][c] = src_val
            elif output[r_bottom][c] == 0:  # only fill 0s, leave background alone
                pass

print("\nPrediction:")
for r, row in enumerate(output):
    print(f"{r}: {row}")

